function salvageMaterial(d){return !!(d?.material&&MATERIALS[d.material.id]&&Number.isSafeInteger(d.material.count)&&d.material.count>0&&Number.isFinite(d.x)&&Number.isFinite(d.y));}
function salvagePullValid(s){return s.owner===p&&s.world===dungeon&&!s.finished&&!dead&&p?.hp>0&&dist(p,s.origin)<=500&&lineClear(p,s.origin);}
const salvagePullCastBase=castCraftedSkill;castCraftedSkill=(build,...args)=>{let result=salvagePullCastBase(build,...args);if(GEM[build.type]?.signature!==99)return result;let s=signatureSpells.at(-1);if(s?.mode!==99)return result;signatureSpells=signatureSpells.filter(v=>v.mode!==99||v===s);s.owner=p;s.world=dungeon;s.finished=false;s.target=null;s.x=s.origin.x;s.y=s.origin.y;s.materials=drops.filter(d=>salvageMaterial(d)&&dist(d,s.origin)<=420&&lineClear(s.origin,d)).sort((a,b)=>dist(a,s.origin)-dist(b,s.origin)).slice(0,16).map((drop,i)=>{let angle=i*Math.PI*2/16,target={x:s.origin.x+Math.cos(angle)*24,y:s.origin.y+Math.sin(angle)*24};if(!passable(target.x,target.y,0)||!lineClear(drop,target))target={...s.origin};return{drop,target};});return result;};
const salvagePullStepBase=stepSignature;stepSignature=(s,dt)=>{if(s.mode!==99)return salvagePullStepBase(s,dt);if(!salvagePullValid(s))return false;if(paused||!Number.isFinite(dt)||dt<=0)return true;let step=Math.min(dt,Math.max(0,2-s.time));s.time+=step;
 s.materials=s.materials.filter(({drop})=>drops.includes(drop)&&salvageMaterial(drop));for(let {drop,target}of s.materials){let distance=dist(drop,target);if(distance<=1e-8||!lineClear(drop,target)||!passable(target.x,target.y,0))continue;let amount=Math.min(distance,240*step);drop.x+=(target.x-drop.x)/distance*amount;drop.y+=(target.y-drop.y)/distance*amount;}
 if(s.time+1e-8>=2||!s.materials.length){s.finished=true;return false;}return true;};
const salvagePullPaintBase=paintSignatureSpells;paintSignatureSpells=()=>{salvagePullPaintBase();const renderList=signatureRenderList(99,99);if(!renderList.length)return;for(const s of renderList){if(s.mode!==99||!salvagePullValid(s)||!visibleAt(s.x,s.y))continue;let color=ELEMENTS[s.build.elements[0]].color;groundRing(s.x,s.y,24,color,2);groundRing(s.x,s.y,50+10*Math.sin(s.time*8),color,1);for(let {drop}of s.materials)if(drops.includes(drop)&&visibleAt(drop.x,drop.y))paintLinkLine(drop,s.origin,color,1);}};
const salvagePullStatusBase=controlSkillStatus;controlSkillStatus=s=>s.mode===99?{label:'素材の引力',value:Math.max(0,1-s.time/2),waiting:true}:salvagePullStatusBase(s);
